{"path": "two_bucket.py", "content": "from collections import deque


def measure(bucket_one, bucket_two, goal, start_bucket):
    """Return (moves, goal_bucket, other_bucket_liters) using a breadth-first search."""
    if start_bucket not in ("one", "two"):
        raise ValueError("start_bucket must be 'one' or 'two'")
    if goal > max(bucket_one, bucket_two):
        raise ValueError("goal is larger than both buckets")

    sizes = (bucket_one, bucket_two)
    start_index = 0 if start_bucket == "one" else 1
    other_index = 1 - start_index

    def forbidden(state):
        return state[start_index] == 0 and state[other_index] == sizes[other_index]

    def next_states(state):
        a, b = state
        pour_ab = min(a, bucket_two - b)
        pour_ba = min(b, bucket_one - a)
        return [
            (bucket_one, b),
            (a, bucket_two),
            (0, b),
            (a, 0),
            (a - pour_ab, b + pour_ab),
            (a + pour_ba, b - pour_ba),
        ]

    first = [0, 0]
    first[start_index] = sizes[start_index]
    first = tuple(first)

    queue = deque([(first, 1)])
    seen = {(0, 0), first}
    while queue:
        state, moves = queue.popleft()
        if state[0] == goal:
            return moves, "one", state[1]
        if state[1] == goal:
            return moves, "two", state[0]
        for nxt in next_states(state):
            if nxt in seen or forbidden(nxt):
                continue
            seen.add(nxt)
            queue.append((nxt, moves + 1))

    raise ValueError("goal is not reachable with the given buckets")
